import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, smoothstep, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Vector3,
  } = THREE;

  const root = new Group();
  const timelines = [];
  const primitiveCleanups = [];
  const geometries = [];
  const materials = [];
  const textures = [];

  const addGeometry = (geometry) => {
    geometries.push(geometry);
    return geometry;
  };

  const addMaterial = (material) => {
    materials.push(material);
    return material;
  };

  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  const backdropGeometry = addGeometry(new PlaneGeometry(7, 6));
  const backdropMaterial = addMaterial(new MeshBasicNodeMaterial());
  backdropMaterial.colorNode = mix(
    vec3(0.011, 0.011, 0.016),
    mix(
      vec3(0.086, 0.086, 0.114),
      vec3(0.043, 0.043, 0.055),
      smoothstep(0.15, 0.85, uv().y)
    ),
    smoothstep(0.02, 0.98, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const shadowGeometry = addGeometry(new CircleGeometry(1.85, 64));
  const shadowMaterial = addMaterial(
    new MeshBasicNodeMaterial({
      color: surface,
      transparent: true,
      opacity: 0.48,
      depthWrite: false,
    })
  );
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.rotation.x = -Math.PI / 2;
  shadow.scale.set(1.45, 0.48, 1);
  shadow.position.set(0, -1.13, -0.72);
  root.add(shadow);

  const cardGroup = new Group();
  cardGroup.position.z = 0.15;
  root.add(cardGroup);

  const cardWidth = 3.15;
  const cardHeight = 1.92;

  const cardBackGeometry = addGeometry(
    new PlaneGeometry(cardWidth, cardHeight)
  );
  const cardBackMaterial = addMaterial(
    new MeshBasicNodeMaterial({ color: ink })
  );
  const cardBack = new Mesh(cardBackGeometry, cardBackMaterial);
  cardBack.position.z = -0.035;
  cardGroup.add(cardBack);

  const imageGeometry = addGeometry(
    new PlaneGeometry(cardWidth - 0.12, cardHeight - 0.12)
  );
  const imageMaterial = addMaterial(
    new MeshBasicNodeMaterial({
      color: paper,
      transparent: true,
    })
  );
  const imagePanel = new Mesh(imageGeometry, imageMaterial);
  imagePanel.position.z = 0.01;
  cardGroup.add(imagePanel);

  const topEdgeGeometry = addGeometry(
    new BoxGeometry(cardWidth + 0.08, 0.035, 0.045)
  );
  const edgeMaterial = addMaterial(
    new MeshBasicNodeMaterial({
      color: accent,
      transparent: true,
      opacity: 0.82,
    })
  );
  const topEdge = new Mesh(topEdgeGeometry, edgeMaterial);
  topEdge.position.set(0, cardHeight * 0.5 + 0.015, 0.075);
  cardGroup.add(topEdge);

  const sideEdgeGeometry = addGeometry(
    new BoxGeometry(0.035, cardHeight + 0.08, 0.045)
  );
  const sideEdge = new Mesh(sideEdgeGeometry, edgeMaterial);
  sideEdge.position.set(cardWidth * 0.5 + 0.015, 0, 0.075);
  cardGroup.add(sideEdge);

  const innerLineGeometry = addGeometry(
    new BoxGeometry(cardWidth - 0.54, 0.012, 0.025)
  );
  const innerLineMaterial = addMaterial(
    new MeshBasicNodeMaterial({
      color: paper,
      transparent: true,
      opacity: 0.34,
    })
  );
  const innerLine = new Mesh(innerLineGeometry, innerLineMaterial);
  innerLine.position.set(-0.14, -0.39, 0.075);
  cardGroup.add(innerLine);

  const loadedTexture = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl)
    : null;

  if (loadedTexture) {
    loadedTexture
      .then((texture) => {
        if (root.userData.disposed) {
          texture.dispose?.();
          return;
        }

        textures.push(texture);
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;
      })
      .catch(() => {});
  }

  const textItems =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of textItems) {
    if (!item || typeof item.text !== 'string') continue;

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'accent' ? accent : paper,
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx,
    });

    textObject.position.set(
      item.position?.x ?? -1.25,
      item.position?.y ?? 0,
      item.position?.z ?? 0.1
    );
    cardGroup.add(textObject);
  }

  const basePosition = cardGroup.position.clone();
  const baseScale = cardGroup.scale.clone();

  const riseIn = gsap.timeline({ paused: true });
  riseIn.fromTo(
    cardGroup.position,
    { y: basePosition.y + 0.15 },
    {
      y: basePosition.y,
      duration: 0.7,
      ease: 'power3.out',
    }
  );
  timelines.push(riseIn);

  const pressDown = gsap.timeline({ paused: true });
  pressDown.to(cardGroup.scale, {
    x: baseScale.x * 0.97,
    y: baseScale.y * 0.97,
    z: baseScale.z * 0.97,
    duration: 0.12,
    ease: 'power2.out',
  });
  pressDown.to(cardGroup.scale, {
    x: baseScale.x,
    y: baseScale.y,
    z: baseScale.z,
    duration: 0.28,
    ease: 'back.out(2)',
  });
  timelines.push(pressDown);

  const focusIn = gsap.timeline({ paused: true });
  focusIn.to([topEdge.material, sideEdge.material], {
    opacity: 1,
    duration: 0.2,
    ease: 'power2.out',
  });
  timelines.push(focusIn);

  const focusOut = gsap.timeline({ paused: true });
  focusOut.to([topEdge.material, sideEdge.material], {
    opacity: 0.82,
    duration: 0.2,
    ease: 'power2.out',
  });
  timelines.push(focusOut);

  const interactions = config.behaviorSpec?.interactions ?? [];

  root.userData.handlers = {
    hover(active = true) {
      if (active === false) {
        gsap.to(cardGroup.position, {
          y: basePosition.y,
          duration: 0.3,
          ease: 'power2.out',
        });
        return;
      }

      gsap.to(cardGroup.position, {
        y: basePosition.y + 0.15,
        duration: 0.3,
        ease: 'power2.out',
      });
    },

    pointerenter() {
      root.userData.handlers.hover(true);
    },

    pointerleave() {
      root.userData.handlers.hover(false);
    },

    click() {
      pressDown.restart();
      ctx.emit('hub-pricing.select', {
        node: config.id ?? config.nodeId ?? 'pricing-quote-panel',
      });
    },

    focus() {
      focusOut.pause(0);
      focusIn.restart();
    },

    blur() {
      focusIn.pause(0);
      focusOut.restart();
    },
  };

  for (const interaction of interactions) {
    if (interaction?.event === 'hover') {
      root.userData.handlers.hover;
    }
  }

  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    if (!primitive?.name || !ctx.primitives?.[primitive.name]) continue;

    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result?.timeline) timelines.push(result.timeline);
    if (result?.cleanup) primitiveCleanups.push(result.cleanup);
  }

  root.userData.cleanup = () => {
    if (root.userData.disposed) return;
    root.userData.disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const cleanup of primitiveCleanups) {
      cleanup?.();
    }

    for (const texture of textures) {
      texture.dispose?.();
    }

    for (const material of materials) {
      material.dispose?.();
    }

    for (const geometry of geometries) {
      geometry.dispose?.();
    }

    root.clear();
  };

  return root;
}
